import { useEffect, useState } from "react";

export default function AdminGallery() {
  const [images, setImages] = useState([]);

  const fetchImages = async () => {
    const res = await fetch("http://localhost:5001/admin/gallery", {
      headers: {
        Authorization: "Bearer " + localStorage.getItem("adminToken"),
      },
    });
    const data = await res.json();
    setImages(data);
  };

  useEffect(() => {
    fetchImages();
  }, []);

  const upload = async (e) => {
    const form = new FormData();
    form.append("image", e.target.files[0]);

    await fetch("http://localhost:5001/admin/gallery", {
      method: "POST",
      headers: {
        Authorization: "Bearer " + localStorage.getItem("adminToken"),
      },
      body: form,
    });

    fetchImages();
  };

  const remove = async (id) => {
    await fetch(`http://localhost:5001/admin/gallery/${id}`, {
      method: "DELETE",
      headers: {
        Authorization: "Bearer " + localStorage.getItem("adminToken"),
      },
    });

    fetchImages();
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-yellow-400 mb-6">
        Gallery Manager
      </h2>

      <input
        type="file"
        onChange={upload}
        className="mb-8 text-white"
      />

      <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
        {images.map((img) => (
          <div
            key={img._id}
            className="relative border border-white/10 rounded-xl overflow-hidden"
          >
            <img
              src={`http://localhost:5001/uploads/${img.filename}`}
              alt=""
              className="w-full h-40 object-cover"
            />

            <button
              onClick={() => remove(img._id)}
              className="absolute top-2 right-2 bg-red-600 px-3 py-1 text-sm rounded"
            >
              Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
